operations.schema:
input InitOrganizationInput {
  handle: String!
  name: String!
  createdBy: EthereumAddress!
}

input SetOrgProfileInput {
  name: String
  bio: String
  website: String
  avatar: String
  links: [SetOrgProfileLinkInput!]
}

input SetOrgProfileLinkInput {
  id: OID!
  label: String!
  url: String!
}

input SetOrgHandleInput {
  handle: String!
}

input SetOrgListedInput {
  listed: Boolean!
}

input SetMembersPublicInput {
  membersPublic: Boolean!
}

input ArchiveOrgInput {
  archivedAt: DateTime!
}

input SetTakenDownInput {
  takenDown: Boolean!
}

input InviteMemberInput {
  id: OID!
  address: EthereumAddress!
  role: RenownOrgRole!
  invitedAt: DateTime!
}

input SetMemberStatusInput {
  id: OID!
  status: RenownOrgMemberStatus!
  at: DateTime!
}

input SetMemberRoleInput {
  id: OID!
  role: RenownOrgRole!
  at: DateTime!
}

input SetMemberAppScopeInput {
  id: OID!
  all: Boolean!
  appDids: [String!]!
  at: DateTime!
}

input SetMemberHiddenInput {
  id: OID!
  hidden: Boolean!
  at: DateTime!
}

input AddTeamInput {
  id: OID!
  slug: String!
  name: String!
  appDids: [String!]!
}

input UpdateTeamInput {
  id: OID!
  slug: String
  name: String
  appDids: [String!]
}

input RemoveTeamInput {
  id: OID!
}

input SetTeamMembersInput {
  id: OID!
  memberIds: [OID!]!
}

input AddOrgAppInput {
  appDid: String!
  addedAt: DateTime!
}

input RemoveOrgAppInput {
  appDid: String!
}

input SetAppFrozenInput {
  appDid: String!
  frozen: Boolean!
}

input AddDomainInput {
  id: OID!
  domain: String!
}

input SetDomainStatusInput {
  id: OID!
  status: RenownOrgDomainStatus!
  verifiedAt: DateTime
}

input RemoveDomainInput {
  id: OID!
}

input SuspendCredentialsInput {
  credentialIds: [String!]!
}

input UnsuspendCredentialInput {
  credentialId: String!
}
